 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    groups = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            y0, x0 = min(y for y,x in cells), min(x for y,x in cells)
            pts = {(y-y0, x-x0) for y,x in cells}
            hh = max(y for y,x in pts) + 1
            ww = max(x for y,x in pts) + 1
            frame = all((y,x) in pts for y in range(hh) for x in range(ww)
                        if y == 0 or y == hh-1 or x == 0 or x == ww-1)
            groups.append((color, y0, x0, pts, hh, ww, frame))

    out = [[0] * w for _ in range(h)]
    # Complete perimeter frames pack upward; open/incomplete forms pack downward.
    # Place objects in their original left-to-right lanes, preserving their shapes.
    for frame_value in (True, False):
        items = sorted((g for g in groups if g[6] == frame_value), key=lambda g: (g[1], g[2]))
        for color, y0, x0, pts, hh, ww, frame in items:
            candidates = range(0, h-hh+1) if frame else range(h-hh, -1, -1)
            for ay in candidates:
                if all(out[ay+dy][x0+dx] == 0 for dy,dx in pts):
                    for dy,dx in pts:
                        out[ay+dy][x0+dx] = color
                    break
    return out
